\begin{tikzpicture}[font=\sffamily, scale=0.9]
    % Draw grid
    \draw[lightgray!50, very thin] (-2.5, -4.5) grid (4.5, 6.5);

    % Axes
    \draw[-Stealth, thick] (-2.8, 0) -- (4.8, 0) node[right] {$x$};
    \draw[-Stealth, thick] (0, -4.8) -- (0, 7.2) node[above] {$y$};

    % Axis ticks and labels
    \foreach \x in {-2, -1, 1, 2, 3, 4} {
        \draw (\x, 0.1) -- (\x, -0.1) node[below=2pt, font=\small] {\x};
    }
    \foreach \y in {-4, -3, -2, -1, 1, 2, 3, 4, 5, 6} {
        \draw (0.1, \y) -- (-0.1, \y) node[left=2pt, font=\small] {\y};
    }
    \node at (-0.3, -0.3) [font=\small] {0};

\end{tikzpicture}
